/*SELECT  "Code"as  "CombinedEntry",  T2."U_AbsEntry"as "AbsEntry", T2."U_Line" as "Line", T2."U_srcPath" as "srcPath",  T2."U_trgtPath"as "TargetPath",   T2."U_FileName"as  "FileName",    T2."U_FileExt"as "FileText",     T2."U_Date"as "Date",      T2."U_UsrID"as "UserId",       T2."U_CardCode" as "CardCode"    FROM      "@TNX_ATC1" T2 WHERE  T2."Code" Not in (Select  T1."AbsEntry" || '-' || T1."Line" from "ATC1" T1  INNER JOIN      OCRD T0 ON T0."AtcEntry" = T1."AbsEntry" WHERE T0."CardCode" = T2."U_CardCode")*/   SELECT  "Code"as  "CombinedEntry",  T2."U_AbsEntry"as "AbsEntry", T2."U_Line" as "Line", T2."U_srcPath" as "srcPath",  T2."U_trgtPath"as "TargetPath",   T2."U_FileName"as  "FileName",    T2."U_FileExt"as "FileText",     T2."U_Date"as "Date",      T2."U_UsrID"as "UserId",       T2."U_CardCode" as "CardCode"    FROM      "@TNX_ATC1" T2 WHERE  (  "U_FileName","U_CardCode") NOT IN (        SELECT  "FileName","CardCode"   from "ATC1" T1  INNER JOIN      OCRD T0 ON T0."AtcEntry" = T1."AbsEntry" WHERE T0."CardCode" = T2."U_CardCode")  ---T2."Code" Not in (Select  T1."AbsEntry" || '-' || T1."Line" from "ATC1" T1  INNER JOIN    ---  OCRD T0 ON T0."AtcEntry" = T1."AbsEntry" WHERE T0."CardCode" = T2."U_CardCode")
